const ee = require('@google/earthengine'); 
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const sanJose = ee.Geometry.Point([-121.8887, 37.3382]);
    const region = sanJose.buffer(50000); // 50 km buffer around San Jose

    const dateJuneStart = '2020-06-01';
    const dateJuneEnd = '2020-06-30';
    const dateAugStart = '2020-08-20'; // Window around Aug 26
    const dateAugEnd = '2020-09-01';

    const scale = 300; // Use a larger scale to avoid maxPixels issues and speed up

    // Sentinel-2 cloud masking function
    function maskS2clouds(image) {
      const qa = image.select('SCL');
      // Pixels to mask: clouds, cirrus, snow/ice, cloud shadows, saturated
      const mask = qa.neq(3) // Cloud shadows
        .and(qa.neq(8)) // Medium probability clouds
        .and(qa.neq(9)) // High probability clouds
        .and(qa.neq(10)) // Cirrus
        .and(qa.neq(11)); // Snow/Ice
      return image.updateMask(mask).divide(10000); // Scale to SR values
    }

    // NBR calculation function
    function calculateNBR(image) {
      // Sentinel-2 bands for NBR: B8 (NIR) and B12 (SWIR2)
      return image.normalizedDifference(['B8', 'B12']).rename('NBR');
    }

    // Function to calculate burn scar area for a given date range
    async function getBurnScarArea(startDate, endDate, periodName) {
      const collection = ee.ImageCollection('COPERNICUS/S2_SR')
        .filterBounds(region)
        .filterDate(startDate, endDate)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)); // Pre-filter by cloud percentage

      const colSize = await collection.size().getInfo();
      if (colSize === 0) {
        console.log(`No Sentinel-2 images found for ${periodName} (${startDate} - ${endDate}).`);
        return { area: null, count: 0, cloud_pct: null, col_size: colSize };
      }

      const maskedCollection = collection.map(maskS2clouds);
      const medianImage = maskedCollection.median();

      const nbrImage = calculateNBR(medianImage);

      // A typical NBR threshold for burned areas is below -0.1 to -0.2.
      // Let's use -0.1 as a conservative threshold for initial detection.
      const burnedAreaMask = nbrImage.lt(-0.1);

      // Calculate pixel count after masking for NBR calculation and burn scar detection
      const totalPixels = await medianImage.select('B8').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).get('B8').getInfo();

      if (totalPixels === 0) {
        console.log(`No valid pixels remaining for ${periodName} after cloud masking.`);
        return { area: 0, count: 0, cloud_pct: null, col_size: colSize };
      }

      const burnScarPixels = await burnedAreaMask.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).get('NBR').getInfo();

      const pixelAreaSqM = scale * scale; // Area of one pixel in square meters
      const burnScarAreaSqKm = (burnScarPixels * pixelAreaSqM) / 1e6; // Convert to square km

      // Calculate approximate cloud percentage (based on initially filtered images)
      // This is a rough estimate for output, not for strict masking.
      const firstImageCloudPct = await collection.first().get('CLOUDY_PIXEL_PERCENTAGE').getInfo();
      const avgCloudPct = firstImageCloudPct !== null ? parseFloat(firstImageCloudPct).toFixed(2) : 'N/A';

      console.log(`${periodName} Images: ${colSize} (Avg Cloud: ${avgCloudPct}%)`);
      console.log(`${periodName} Valid Pixels for NBR calc: ${totalPixels}`);
      console.log(`${periodName} Burned Pixels: ${parseInt(burnScarPixels)}`);

      return { 
        area: burnScarAreaSqKm, 
        count: totalPixels, 
        cloud_pct: avgCloudPct,
        col_size: colSize
      };
    }

    // 2. Data Acquisition & Check and Processing for June
    const juneStats = await getBurnScarArea(dateJuneStart, dateJuneEnd, 'June');

    // 3. Data Acquisition & Check and Processing for August
    const augustStats = await getBurnScarArea(dateAugStart, dateAugEnd, 'August');

    // 4. Calculation and Validation
    if (juneStats.col_size === 0 || augustStats.col_size === 0) {
      console.log("C1: Empty Collection (No images found in date/location for one or both comparison points).");
      console.log("C1");
      return;
    }

    if (juneStats.count === 0 || augustStats.count === 0) {
      console.log("C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).");
      console.log("C2");
      return;
    }

    if (juneStats.area === null || isNaN(juneStats.area) || augustStats.area === null || isNaN(augustStats.area)) {
      console.log("C3: Calculation Failure (Burn scar area is None, NaN, or invalid).");
      console.log("C3");
      return;
    }

    console.log(`June 2020 Burn Scar Area: ${juneStats.area.toFixed(2)} sq km`);
    console.log(`August 2020 Burn Scar Area: ${augustStats.area.toFixed(2)} sq km`);

    if (augustStats.area > juneStats.area) {
      console.log("A"); // Yes
    } else {
      console.log("B"); // No
    }

  } catch (error) {
    console.error("An error occurred during analysis:", error);
    if (error.message.includes("does not exist") || error.message.includes("Cannot read properties of null")) {
      console.log("D"); // Likely incorrect band name, image, or collection name
    } else {
      console.log("C3"); // Other calculation failure
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
